// Read-only constants of the USER'S OWN golf_clean.exe, addressed by model descriptor name (phase 3.0, 2026-10-19).
//
// Decision (re/model/DECISIONS.md, phase 1): constant tables and strings stay in the user's exe; the port carries only
// DESCRIPTORS (execonst_desc.inc, generated by re/tools/execonst_gen.py from re/model/f_descriptors.tsv: symbol, file
// offset, size, element type, count, stride, kind, and the sgh64 of the bytes in the anchored exe). ExeConstants loads
// an exe from a path the caller gives at startup, checks that it is the expected build (the .data section's size equals
// sizeof(GameState), and every descriptor's bytes hash to the recorded value) and then serves:
//   - bytes(name) / get<T>(name, i): a descriptor's bytes (any section: .rdata scalars such as f_k_dbl_*, IATs, string
//     pools, .data tables);
//   - fill_state(gs, mode): the initial values of the GameState from the file's initialised .data, either only the
//     objects of class `const` (ConstObjects) or the whole initialised image as the Windows loader maps it
//     (InitialImage: every object the file initialises, the bss stays zero).
// Port functions read `const`-class GameState objects (string pools, f_tab_* tables) as ordinary GameState members;
// those bytes come from fill_state at startup and from the corpus's seed regions in vector tests. Tables the original
// computes at run time (g_sinTable by initSinTable, g_tileTypeAttrs copied by the course loader) are NOT in the file:
// their initialisers are port functions of their own.
//
// The test harness loads the exe named by $SG_EXE_PATH, else original/golf_clean.exe (port/test/README.md).
#ifndef PORTSIM_EXECONST_H
#define PORTSIM_EXECONST_H

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#include "gamestate.h"
#include "portsim/registry.h"

namespace portsim {

struct ExeConstDesc {
  const char *name;
  uint32_t file_off, size;
  const char *elem;  // model element type: int32_t, double, char[], ptr, a struct name ...
  uint32_t count, stride;  // stride 0 = variable (string pools)
  const char *kind;  // const_table, const_scalar, string_pool, import_address_table, ...
  uint64_t hash;     // sgh64 of the bytes in the anchored exe
};

class ExeConstants {
 public:
  enum class Fill { ConstObjects, InitialImage };

  // Load and verify. On failure returns false, leaves the object empty and writes a reason to *err.
  bool load_file(const char *path, std::string *err);
  bool load_bytes(const uint8_t *data, size_t n, std::string *err);
  bool loaded() const { return !file_.empty(); }

  static const std::vector<ExeConstDesc> &descriptors();
  static const ExeConstDesc *find(const char *name);  // nullptr when unknown

  // a descriptor's bytes; throws MissingResource when not loaded or unknown
  const uint8_t *bytes(const char *name, uint32_t *size = nullptr) const;
  // element i (at i * stride, or i * sizeof(T) for a variable stride), bounds-checked against the descriptor
  template <class T> T get(const char *name, uint32_t i = 0) const {
    uint32_t size = 0;
    const uint8_t *p = bytes(name, &size);
    const ExeConstDesc *d = find(name);
    const uint32_t step = d->stride ? d->stride : static_cast<uint32_t>(sizeof(T));
    if (static_cast<uint64_t>(i) * step + sizeof(T) > size) throw MissingResource{"exe constant index out of range"};
    T v;
    std::memcpy(&v, p + static_cast<size_t>(i) * step, sizeof(T));
    return v;
  }

  // the file's initialised .data (raw size <= sizeof(GameState))
  const uint8_t *data_raw() const { return file_.data() + data_off_; }
  uint32_t data_raw_size() const { return data_raw_size_; }
  void fill_state(GameState &gs, Fill mode) const;

 private:
  std::vector<uint8_t> file_;
  uint32_t data_off_ = 0, data_raw_size_ = 0;
};

// The process-wide instance the C ABI loads (sg_exe_load) and attaches to contexts.
ExeConstants &default_exe_constants();

}  // namespace portsim

#endif  // PORTSIM_EXECONST_H
